    /// </summary>
    public nuint RequiredDeviceExtensionCount;

    /// <summary>
    /// Enable every one of these device extensions (you may enable more). Static strings, valid for
    /// the life of the process (FreeMembers does not free them).
    /// </summary>
    public CodebrixName* RequiredDeviceExtensions;

    /// <summary>
    /// A <c>VkPhysicalDeviceFeatures2*</c> with its <c>pNext</c> chain of the feature structures wgpu enables,
    /// OWNED by the library until FreeMembers. Put it into <c>VkDeviceCreateInfo::pNext</c> (with
    /// <c>pEnabledFeatures</c> NULL), or copy it and OR in features of your own - never enable fewer. To
    /// chain structures of your own, put them in front of it; never write into it.
    /// </summary>
    public void* PhysicalDeviceFeatures2;

    /// <summary>
    /// The physical device's <c>VkPhysicalDeviceProperties::apiVersion</c>.
    /// </summary>
    public uint PhysicalDeviceApiVersion;
}

/// <summary>
/// The Vulkan objects behind a wgpu device. All handles are the raw <c>VkInstance</c>, <c>VkPhysicalDevice</c>,
/// <c>VkDevice</c> and <c>VkQueue</c> values; they stay owned by wgpu and are valid while the device is alive.
/// Exactly what SkiaSharp's <c>GRVkBackendContext</c> needs to create a <c>GRContext</c> on the same device.
/// Filled by <see cref="WebGpu.CodebrixDeviceGetVulkanInfo" />.
/// </summary>
/// <remarks>C type: <c>WGPUCodebrixVulkanDeviceInfo</c>.</remarks>
[StructLayout(LayoutKind.Sequential)]
public unsafe struct CodebrixVulkanDeviceInfo
{
    /// <summary>
    /// <c>VkInstance</c>.
    /// </summary>
    public void* Instance;

    /// <summary>
    /// <c>VkPhysicalDevice</c>.
    /// </summary>
    public void* PhysicalDevice;

    /// <summary>
    /// <c>VkDevice</c>.
    /// </summary>
    public void* Device;

    /// <summary>
    /// <c>VkQueue</c> - the queue wgpu submits to.
    /// </summary>
    public void* Queue;

    /// <summary>
    /// The family index of <c>queue</c>.
    /// </summary>
    public uint QueueFamilyIndex;

    /// <summary>
    /// The index of <c>queue</c> within its family.
    /// </summary>
    public uint QueueIndex;

    /// <summary>
    /// The <c>VkApplicationInfo::apiVersion</c> the instance was created with (<c>VK_MAKE_API_VERSION</c>
    /// packed). For an instance wgpu created this is wgpu-hal's rule: 1.0 when the Vulkan loader
    /// reports less than 1.1 (<c>vkEnumerateInstanceVersion</c>), otherwise exactly 1.3 (wgpu-hal's maximum)
    /// - so a 1.4 loader still gives 1.3, and no 1.4 entry point is loaded. For an adopted device it is
    /// the <c>instance_api_version</c> of its <see cref="CodebrixVulkanAdoptDescriptor" />. This is the value
    /// Skia's <c>MaxAPIVersion</c> and another adopt descriptor expect. (Vulkan's own rule still applies on
    /// top: device-level functionality is limited to the lower of this and the physical device's
    /// <c>apiVersion</c>.)
    /// </summary>
    public uint InstanceApiVersion;

    /// <summary>
    /// The <c>vkGetInstanceProcAddr</c> entry point wgpu loaded Vulkan through, as a plain function
    /// pointer. SkiaSharp's <c>GRVkGetProcedureAddressDelegate</c> can be built over it.
    /// </summary>
    public void* GetInstanceProcAddr;

    /// <summary>
    /// The number of elements in <see cref="CodebrixVulkanDeviceInfo.EnabledInstanceExtensions" />.
    /// </summary>
    public nuint EnabledInstanceExtensionCount;

    /// <summary>
    /// The instance extension names wgpu enabled. Static strings; valid for the life of the device.
    /// </summary>
    public CodebrixName* EnabledInstanceExtensions;

    /// <summary>
    /// The number of elements in <see cref="CodebrixVulkanDeviceInfo.EnabledDeviceExtensions" />.
    /// </summary>
    public nuint EnabledDeviceExtensionCount;

    /// <summary>
    /// The device extension names wgpu enabled. Static strings; valid for the life of the device.
    /// </summary>
    public CodebrixName* EnabledDeviceExtensions;
}

